  function conditionLabelTool(id){const p=toolConditionPct(id);return p<=0?'Hors service':p<30?'Très usé':p<60?'Usé':p<85?'Bon état':'Excellent état';}
  window.breederBuyTool=id=>{const t=tool(id);if(!t||ownsTool(id)||!meetsGate(t))return;const price=Number(t.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S().ownedTools.push(id);S().toolCondition[id]=toolMax(id);S().toolXp[id]=0;if(!S().equippedTools[t.actionId])S().equippedTools[t.actionId]=id;S().stats.toolsBought++;S().stats.equipmentSpent+=price;C.log(`🧰 Outil Éleveur acheté : ${t.name}.`);C.save();render();};
  window.breederEquipTool=id=>{const t=tool(id);if(!t||!ownsTool(id)||!meetsGate(t))return;S().equippedTools[t.actionId]=id;C.log(`🧰 ${t.name} équipé pour ${actions().find(a=>a.id===t.actionId)?.name||t.actionId}.`);C.save();render();};
  window.breederRepairTool=id=>{const t=tool(id);if(!t||!ownsTool(id)||toolCondition(id)>=toolMax(id)-.5)return;const cost=repairCost(id);if(cost<=0&&t.starter&&toolCondition(id)<=0){S().toolCondition[id]=Math.round(toolMax(id)*.25);C.log(`🔧 Remise en état de secours : ${t.name} revient à 25 %.`);}else{if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronnes.`);C.state.treasury-=cost;S().toolCondition[id]=toolMax(id);S().stats.repairs++;S().stats.maintenanceSpent+=cost;C.log(`🔧 ${t.name} entretenu pour ${cost} couronnes.`);}C.save();render();};
  window.breederBuyGear=id=>{const g=gear(id);if(!g||ownsGear(id)||!meetsGate(g))return;const price=Number(g.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S().ownedGear.push(id);if(!S().equippedGear[g.slot])S().equippedGear[g.slot]=id;S().stats.gearBought++;S().stats.equipmentSpent+=price;C.log(`🏚️ Installation Éleveur acquise : ${g.name}.`);C.save();render();};
  window.breederEquipGear=id=>{const g=gear(id);if(!g||!ownsGear(id)||!meetsGate(g))return;S().equippedGear[g.slot]=id;C.log(`🏚️ ${g.name} activé dans l’exploitation.`);C.save();render();};
  function refreshMarket(force=false){const s=S(),t=now();if(!force&&t-Number(s.lastMarketRefresh||0)<90000)return false;for(const m of marketDefs()){const cur=Number(s.marketDemand[m.id]||1),drift=(Math.random()-.5)*.16;s.marketDemand[m.id]=clamp(cur*.78+1*.22+drift,Number(m.minDemand||.7),Number(m.maxDemand||1.5));}s.lastMarketRefresh=t;return true;}
  function marketDemand(id){refreshMarket();return Number(S().marketDemand?.[id]||1);}
  function marketSpecBonus(id){return ['eggs','golden_eggs'].includes(id)?specEffect('eggMarket'):['goat_milk','white_peak_milk'].includes(id)?specEffect('milkMarket'):['wool','mist_wool'].includes(id)?specEffect('woolMarket'):0;}
  function marketPrice(id){const m=marketItem(id);if(!m)return 0;const renown=Math.min(.12,Number(S().reputation||0)*.0012),price=Number(m.basePrice||0)*marketDemand(id)*(1+renown+marketSpecBonus(id)+careerEffect('marketBonus'));return Math.round(price*100)/100;}
  window.breederSellResource=(id,mode='1')=>{refreshMarket();const m=marketItem(id),have=Math.floor(C.resource(id));if(!m||have<=0)return;const qty=mode==='all'?have:Math.min(have,Math.max(1,Number(mode||1))),unit=marketPrice(id),total=Math.round(unit*qty*100)/100;if(!C.consumeResource(id,qty,'Vente marché Éleveur'))return;C.state.treasury=Number(C.state.treasury||0)+total;S().stats.marketSales+=qty;S().stats.marketRevenue+=total;S().marketDemand[id]=clamp(marketDemand(id)-qty*.008,Number(m.minDemand||.7),Number(m.maxDemand||1.5));C.log(`🪙 Vente Éleveur : ${qty} × ${m.name} pour ${total.toFixed(2)} couronnes.`);C.save();render();};
