  function effectText(e={}){const labels={productionYield:'Production globale',welfare:'Bien-être',health:'Santé',decayReduction:'Usure des besoins réduite',fodderSave:'Fourrage économisé',feedingQuality:'Qualité ration',careQuality:'Qualité des soins',careSpeed:'Vitesse des soins',henYield:'Production poules',goatYield:'Production chèvres',sheepYield:'Production moutons',eggMarket:'Prix des œufs',milkMarket:'Prix du lait',woolMarket:'Prix de la laine',henDecayReduction:'Dégradation poules réduite',goatDecayReduction:'Dégradation chèvres réduite',sheepDecayReduction:'Dégradation moutons réduite',henCareQuality:'Soins poules',goatCareQuality:'Soins chèvres',sheepCareQuality:'Soins moutons'};return Object.entries(e).map(([k,v])=>`${labels[k]||k} ${Math.abs(Number(v))<1?`${Number(v)>=0?'+':''}${Math.round(Number(v)*100)}%`:`${Number(v)>=0?'+':''}${v}`}`);}
  function renderEquipment(){ensure();const treasury=Math.round(Number(C.state.treasury||0)),actionLabels=Object.fromEntries(actions().map(a=>[a.id,a.name])),slotLabels={shelter:'Abris & confort',feeding:'Stockage & ration',handling:'Conduite & contention'};$('#breederTools').innerHTML=`<div class="notice subtle">Trésorerie : <b>${treasury} 🪙</b>. Les outils s’usent à chaque soin ; un outil très usé ralentit le travail et apporte moins de précision.</div><div class="equipment-grid">${tools().map(t=>{const open=meetsGate(t),owned=ownsTool(t.id),equipped=S().equippedTools[t.actionId]===t.id,pct=owned?Math.round(toolConditionPct(t.id)):0;return `<article class="equipment-card ${owned?'owned':''} ${equipped?'equipped':''} ${open?'':'locked'}"><div class="equipment-head"><span>${t.icon||'🧰'}</span><div><b>${esc(t.name)}</b><small>${esc(actionLabels[t.actionId]||t.actionId)} · ${owned?`${conditionLabelTool(t.id)} · maîtrise ${toolMastery(t.id)}/10`:`${t.price||0} 🪙`}</small></div></div><p class="muted">${esc(t.description||'')}</p><div class="equipment-stats"><span>Efficacité ×${Number(t.efficiency||1).toFixed(2)}</span><span>Précision +${t.precision||0}</span><span>Durabilité ${t.maxDurability||100}</span></div>${owned?`<div class="durability-row"><span>${pct}%</span><div class="durability-meter"><i style="width:${pct}%"></i></div><b>${conditionLabelTool(t.id)}</b></div><div class="equipment-actions"><button class="btn primary" onclick="breederEquipTool('${t.id}')" ${equipped||!open?'disabled':''}>${equipped?'Équipé':'Équiper'}</button><button class="btn" onclick="breederRepairTool('${t.id}')" ${pct>=99?'disabled':''}>🔧 ${repairCost(t.id)?`Entretenir · ${repairCost(t.id)} 🪙`:'Remise en état'}</button></div>`:`<div class="equipment-actions"><button class="btn primary" onclick="breederBuyTool('${t.id}')" ${!open||treasury<Number(t.price||0)?'disabled':''}>Acheter · ${t.price||0} 🪙</button></div>`}</article>`;}).join('')}</div>`;
    $('#breederGear').innerHTML=`<div class="equipment-grid">${gearDefs().map(g=>{const open=meetsGate(g),owned=ownsGear(g.id),equipped=S().equippedGear[g.slot]===g.id;return `<article class="equipment-card ${owned?'owned':''} ${equipped?'equipped':''} ${open?'':'locked'}"><div class="equipment-head"><span>${g.icon||'🏚️'}</span><div><b>${esc(g.name)}</b><small>${slotLabels[g.slot]||g.slot}${equipped?' · actif':''}</small></div></div><p class="muted">${esc(g.description||'')}</p><div class="equipment-stats">${effectText(g.effects||{}).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="equipment-actions">${owned?`<button class="btn primary" onclick="breederEquipGear('${g.id}')" ${equipped||!open?'disabled':''}>${equipped?'Actif':'Activer'}</button>`:`<button class="btn primary" onclick="breederBuyGear('${g.id}')" ${!open||treasury<Number(g.price||0)?'disabled':''}>Acheter · ${g.price||0} 🪙</button>`}</div></article>`;}).join('')}</div>`;}
  function renderEconomy(){ensure();refreshMarket();const s=S(),income=Number(s.stats.marketRevenue||0)+Number(s.stats.contractRevenue||0)+Number(s.stats.animalRehomeRevenue||0),expenses=Number(s.stats.equipmentSpent||0)+Number(s.stats.maintenanceSpent||0)+Number(s.stats.animalPurchaseSpent||0),net=income-expenses;$('#breederEconomy').innerHTML=`<div class="notice subtle"><b>Marché local :</b> les prix varient avec la demande. La réputation et certaines spécialisations améliorent la valeur des produits, mais vendre toutes les denrées alimentaires peut fragiliser les réserves du village.</div><div class="market-grid">${marketDefs().map(m=>{const have=Math.floor(C.resource(m.id)),d=marketDemand(m.id),price=marketPrice(m.id),r=rs(m.id);return `<article class="market-card"><div class="market-head"><span>${r?.icon||'📦'}</span><div><b>${esc(m.name)}</b><small>Stock ${have} · demande ×${d.toFixed(2)}</small></div><strong>${price.toFixed(2)} 🪙</strong></div><p>${esc(m.description||'')}</p><div class="market-actions"><button class="btn" onclick="breederSellResource('${m.id}','1')" ${have<1?'disabled':''}>Vendre 1</button><button class="btn" onclick="breederSellResource('${m.id}','5')" ${have<1?'disabled':''}>Vendre 5</button><button class="btn primary" onclick="breederSellResource('${m.id}','all')" ${have<1?'disabled':''}>Tout vendre</button></div></article>`;}).join('')}</div>`;$('#breederBalance').innerHTML=`<div class="economy-summary"><div><span>Ventes marché</span><b>${Number(s.stats.marketRevenue||0).toFixed(2)} 🪙</b></div><div><span>Contrats</span><b>${Math.round(s.stats.contractRevenue||0)} 🪙</b></div><div><span>Cessions d’animaux</span><b>${Math.round(s.stats.animalRehomeRevenue||0)} 🪙</b></div><div><span>Achats d’animaux</span><b>−${Math.round(s.stats.animalPurchaseSpent||0)} 🪙</b></div><div><span>Matériel & installations</span><b>−${Math.round(s.stats.equipmentSpent||0)} 🪙</b></div><div><span>Entretien & réorientation</span><b>−${Math.round(s.stats.maintenanceSpent||0)} 🪙</b></div><div><span>Bilan de carrière</span><b>${net>=0?'+':''}${net.toFixed(2)} 🪙</b></div><div><span>Fourrage consommé</span><b>${Math.round(s.stats.fodderConsumed||0)} u.</b></div></div>`;}
