    const pastureEl=$('#breederPastures');if(pastureEl)pastureEl.innerHTML=`<div class="pasture-grid">${pastures().map(d=>{const open=pastureUnlocked(d),st=pastureState(d.id),pct=Math.round(Number(st?.biomass||0)/Math.max(1,Number(d.maxBiomass||100))*100),quality=pastureQuality(d),growth=pastureRegrowthToday(d),seasonFactor=Number(d.seasonGrowth?.[cal.season?.id]??1);return `<article class="pasture-card ${open?'':'locked'}"><div class="market-head"><span>${d.icon||'🌿'}</span><div><b>${esc(d.name)}</b><small>${open?`${pastureConditionLabel(st.condition)} · qualité ${quality}/100`:`🔒 Niv. ${d.minLevel} · grade ${d.minRank} · Étable ${d.minBuildingLevel}`}</small></div><strong>${open?`${pct}%`:'Fermé'}</strong></div><p>${esc(d.description||'')}</p><div class="livestock-needs"><div><span>Herbe</span><i><b style="width:${pct}%"></b></i><strong>${Number(st?.biomass||0).toFixed(1)}/${Number(d.maxBiomass||100)}</strong></div><div><span>État</span><i><b style="width:${clamp(st?.condition)}%"></b></i><strong>${Math.round(st?.condition||0)}%</strong></div></div><div class="requirements compact"><span>Repousse aujourd’hui +${growth.toFixed(1)}</span><span>Saison ×${seasonFactor.toFixed(2)}</span><span>Qualité ${quality}</span></div><div class="pasture-affinities">${species().map(sp=>`<small>${sp.icon} ×${pastureAffinity(d,sp).toFixed(2)}</small>`).join('')}</div></article>`;}).join('')}</div>`;
    const plansEl=$('#breederFeedingPlans');if(plansEl)plansEl.innerHTML=`<div class="feeding-plan-grid">${species().filter(sp=>Number(s.livestock?.[sp.id]?.count||0)>0).map(sp=>{const b=feedBreakdown(sp),pd=currentPasture(sp.id),ps=pd?pastureState(pd.id):null,g=grazingPreview(sp,pd),r=currentRation(sp.id),feedAct=actions().find(a=>a.id==='feed_fodder'),fodderCost=feedAct?actionCost(feedAct,sp):0,warnings=feedingAdvice(sp);return `<article class="feeding-plan-card"><div class="registry-species-head"><span>${sp.icon}</span><div><b>${esc(sp.name)}</b><small>${b.adult} adulte(s) · ${b.young} jeune(s) · ${b.pregnant} gestante(s)</small></div></div><div class="pairing-readout"><span>Besoin pondéré <b>${b.demand.toFixed(1)}</b></span><span>Pâturage <b>${g.cost} herbe</b></span><span>Fourrage <b>${fodderCost} u.</b></span></div><label>Pâture<select onchange="breederSetPasture('${sp.id}',this.value)">${pastures().map(d=>`<option value="${d.id}" ${pd?.id===d.id?'selected':''} ${pastureUnlocked(d)?'':'disabled'}>${d.icon||'🌿'} ${esc(d.name)}${pastureUnlocked(d)?'': ' 🔒'}</option>`).join('')}</select></label><label>Ration de fourrage<select onchange="breederSetRation('${sp.id}',this.value)">${rationDefs().map(x=>`<option value="${x.id}" ${r?.id===x.id?'selected':''} ${rationUnlocked(x)?'':'disabled'}>${x.icon||'🥣'} ${esc(x.name)}${rationUnlocked(x)?'':' 🔒'}</option>`).join('')}</select></label><div class="requirements compact"><span>${esc(pd?.name||'Aucune pâture')} · ${Number(ps?.biomass||0).toFixed(1)} herbe</span><span>Couverture actuelle ${Math.round(g.coverage*100)}%</span><span>Qualité ${g.quality}/100</span><span>${esc(r?.name||'Ration')}</span></div><p class="muted">${esc(r?.description||'')}</p>${warnings.length?`<div class="notice warning">${warnings.map(x=>`<div>⚠️ ${esc(x)}</div>`).join('')}</div>`:'<div class="notice subtle">✓ Plan d’alimentation cohérent avec la situation actuelle.</div>'}</article>`;}).join('')||'<div class="empty-state"><b>Aucun troupeau</b><span>Les plans d’alimentation apparaîtront dès l’arrivée des premiers animaux.</span></div>'}</div>`;
