  function masteryEffectText(e={}){const labels={careQuality:'Qualité des soins',trustGain:'Confiance gagnée',fertility:'Fertilité',productionYield:'Production',contractReward:'Récompenses contrats',marketBonus:'Prix de vente',repairDiscount:'Entretien réduit',activeContractSlots:'Contrat actif supplémentaire'};return Object.entries(e).map(([k,v])=>`${labels[k]||k} ${Math.abs(Number(v))<1?`${Number(v)>=0?'+':''}${Math.round(Number(v)*100)}%`:`${Number(v)>=0?'+':''}${v}`}`);}
  function rewardCareer(r={}){if(r.jobXp)C.gainJobXp(JOB,Number(r.jobXp));if(r.villageXp)C.gainVillageXp(Number(r.villageXp));if(r.reputation)S().reputation=clamp(Number(S().reputation||0)+Number(r.reputation));if(r.treasury)C.state.treasury=Math.max(0,Number(C.state.treasury||0)+Number(r.treasury));if(r.masteryXp)C.gainMastery(JOB,Number(r.masteryXp));}
